css:
.sec{position:relative}
.sec>.body{max-width:32%; margin-inline:auto}
.fig-l{position:absolute; left:2%;  top:40%; width:26%}
.fig-r{position:absolute; right:8%; top:42%; width:18%}
/* 固定幅カラムなら負のオフセットで外へ */
.wrap{max-width:560px; margin-inline:auto; position:relative}
.cut-l{position:absolute; left:-190px; bottom:0; width:150px}
.cut-r{position:absolute; right:-190px; top:20px; width:150px}
@media(max-width:768px){.fig-l,.fig-r{position:static; width:60%}}
